// ✏️ ADD YOUR TARGET COMPANY DOMAINS HERE
// Each domain uses 1 Hunter.io credit (free plan = 25/month)
const domains = [
  "acme.com",
  "example.com",
  "yourprospect.com"
];

const config = $input.first().json;

// Output one item per domain, carrying config along
return domains.map(domain => ({
  json: {
    domain,
    hunterApiKey: config.hunterApiKey,
    campaignUid: config.campaignUid,
    webhookApiKey: config.webhookApiKey,
    apiBaseUrl: config.apiBaseUrl
  }
}));

// HR-related keywords to filter by position/department
const HR_KEYWORDS = [
  'hr', 'human resources', 'people', 'talent', 'recruiting',
  'recruitment', 'staffing', 'workforce', 'personnel'
];

const allItems = $input.all();
const config = $('⚙️ Config (edit me)').first().json;
const leads = [];

for (const item of allItems) {
  const data = item.json.data;
  if (!data || !data.emails) continue;

  const companyName = data.organization || data.domain || '';

  for (const contact of data.emails) {
    // Filter: only keep HR/People/Talent roles
    const position = (contact.position || '').toLowerCase();
    const department = (contact.department || '').toLowerCase();
    const isHR = HR_KEYWORDS.some(kw => position.includes(kw) || department.includes(kw));
    if (!isHR) continue;

    // Skip low-confidence emails
    if ((contact.confidence || 0) < 50) continue;

    const firstName = (contact.first_name || '').trim();
    const lastName = (contact.last_name || '').trim();
    const name = [firstName, lastName].filter(Boolean).join(' ');

    if (!name && !companyName) continue;

    const noteParts = [
      contact.position || null,
      contact.department || null,
      contact.seniority ? `Seniority: ${contact.seniority}` : null
    ].filter(Boolean);

    leads.push({
      name: name || companyName,
      company: companyName,
      email: contact.value || null,
      linkedinUrl: contact.linkedin_url || null,
      notes: noteParts.length > 0 ? noteParts.join(' | ') : null
    });
  }
}

if (leads.length === 0) {
  return [{ json: { leads: [], skipped: true, reason: 'No HR contacts found in any domain' } }];
}

return [{
  json: {
    leads,
    campaignUid: config.campaignUid,
    webhookApiKey: config.webhookApiKey,
    apiBaseUrl: config.apiBaseUrl,
    totalFound: leads.length
  }
}];

